/**
 * Push Notification Handlers for Service Worker
 *
 * This file contains event handlers for Web Push notifications.
 * It will be imported into the main service worker generated by VitePWA.
 */

/**
 * Handle incoming push notifications
 *
 * Receives push messages from the backend and displays them as notifications
 */
self.addEventListener('push', (event) => {
	console.log('🔔 Push notification received')

	let data = {}

	try {
		if (event.data) {
			data = event.data.json()
			console.log('📨 Push data:', data)
		}
	} catch (error) {
		console.error('❌ Error parsing push event data:', error)
		// Use default values if parsing fails
		data = {
			title: 'Notification',
			body: 'You have a new notification'
		}
	}

	const title = data.title || 'Notification'
	const options = {
		body: data.body || '',
		icon: '/android/android-launchericon-192-192.png',
		badge: '/android/android-launchericon-96-96.png',
		data: data,
		tag: data.downtime_log || undefined, // Group notifications by downtime log
		renotify: true, // Alert user even if notification with same tag exists
		requireInteraction: false, // Notification auto-dismisses
		vibrate: [200, 100, 200] // Vibration pattern for mobile devices
	}

	event.waitUntil(
		self.registration.showNotification(title, options)
			.then(() => {
				console.log('✅ Notification displayed successfully')
			})
			.catch((error) => {
				console.error('❌ Error displaying notification:', error)
			})
	)
})

/**
 * Handle notification click events
 *
 * Opens the app and navigates to the relevant page when user clicks notification
 */
self.addEventListener('notificationclick', (event) => {
	console.log('👆 Notification clicked:', event.notification.tag)

	// Close the notification
	event.notification.close()

	const notificationData = event.notification.data || {}
	const targetUrl = notificationData.url || '/frontend/'

	// Open or focus the app window
	event.waitUntil(
		clients.matchAll({
			type: 'window',
			includeUncontrolled: true
		})
		.then((clientList) => {
			console.log(`📱 Found ${clientList.length} open windows`)

			// Check if app is already open
			for (const client of clientList) {
				if (client.url.includes('/frontend') && 'focus' in client) {
					console.log('🎯 Focusing existing window and navigating to:', targetUrl)
					// Send message to app to navigate
					client.postMessage({
						action: 'navigate',
						url: targetUrl
					})
					return client.focus()
				}
			}

			// If no window is open, open a new one
			if (clients.openWindow) {
				console.log('🪟 Opening new window:', targetUrl)
				return clients.openWindow(targetUrl)
			}
		})
		.catch((error) => {
			console.error('❌ Error handling notification click:', error)
		})
	)
})

/**
 * Handle notification close events (optional)
 *
 * Tracks when users dismiss notifications without clicking
 */
self.addEventListener('notificationclose', (event) => {
	console.log('🚫 Notification dismissed:', event.notification.tag)
	// Could send analytics data here if needed
})

console.log('✅ Push notification handlers loaded')
